def browser_go_back(**_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0231000" if __import__("os").path.isdir("./environment_mix/0231000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                d = json.load(f)
                return d if isinstance(d, list) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_01{uuid.uuid4().hex[:25]}".lower()

    def _dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _log_action(actions, session_id, tab_id, status, error_message=None, result=None, related_navigation_id=None):
        now = _now()
        dur = int(max(0, round((time.time() - t0) * 1000)))
        row = {
            "id": _new_id("brws_act"),
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": "browser_go_back",
            "input": {},
            "result": result,
            "related_navigation_id": related_navigation_id,
            "related_snapshot_id": None,
            "related_artifact_id": None,
            "duration_ms": dur,
            "status": status,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
        }
        actions.append(row)
        return row

    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    navs = _load("tab_navigations.json")
    actions = _load("browser_actions.json")

    # Resolve: any ready session that can serve the call, prefer one with an open active tab.
    session = None
    tab = None

    ready_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "ready" and isinstance(s.get("id"), str)]
    # Prefer active_tab_id open
    for s in ready_sessions:
        atid = s.get("active_tab_id")
        if not atid:
            continue
        t = next((tt for tt in tabs if isinstance(tt, dict) and tt.get("id") == atid and tt.get("session_id") == s["id"]), None)
        if t and t.get("status") == "open":
            session, tab = s, t
            break
    # Otherwise pick any open tab and make it active (real backend tends to recover)
    if session is None:
        for s in ready_sessions:
            t = next((tt for tt in tabs if isinstance(tt, dict) and tt.get("session_id") == s["id"] and tt.get("status") == "open"), None)
            if t:
                session, tab = s, t
                s["active_tab_id"] = t.get("id")
                s["updated_at"] = _now()
                break

    if session is None:
        # If there are sessions but none ready, it's a conflict (busy/closed), otherwise not found.
        if any(isinstance(s, dict) and isinstance(s.get("id"), str) for s in sessions):
            return _err("CONFLICT", "No session in 'ready' state is available for browser_go_back.")
        return _err("NOT_FOUND", "No active session/tab found.")

    if tab is None:
        _log_action(actions, session.get("id"), None, "failed", error_message="No active tab found.")
        _save("browser_actions.json", actions)
        return _err("NOT_FOUND", "No active tab found for session.", session_id=session.get("id"))

    if not isinstance(tab.get("history_cursor"), int):
        tab["history_cursor"] = -1

    if tab["history_cursor"] <= 0:
        # CONFLICT per business rule.
        _log_action(
            actions,
            session.get("id"),
            tab.get("id"),
            "failed",
            error_message="No back history entry.",
            result={"history_cursor": tab["history_cursor"]},
        )
        _save("browser_actions.json", actions)
        return _err(
            "CONFLICT",
            "No back history entry.",
            rule="browser_go_back requires browser_tabs.history_cursor > 0",
            history_cursor=tab["history_cursor"],
        )

    target_index = tab["history_cursor"] - 1
    nav = next(
        (n for n in navs if isinstance(n, dict) and n.get("tab_id") == tab.get("id") and n.get("session_id") == session.get("id") and n.get("history_index") == target_index),
        None,
    )
    # Real-world: history may be sparse due to truncation; if exact missing, choose nearest <= target_index.
    if nav is None:
        candidates = [
            n for n in navs
            if isinstance(n, dict) and n.get("tab_id") == tab.get("id") and n.get("session_id") == session.get("id") and isinstance(n.get("history_index"), int) and n.get("history_index") <= target_index
        ]
        if candidates:
            nav = max(candidates, key=lambda x: x.get("history_index"))
            target_index = nav.get("history_index")
        else:
            _log_action(actions, session.get("id"), tab.get("id"), "failed", error_message="Back history entry not found for tab.", result={"history_index": target_index})
            _save("browser_actions.json", actions)
            return _err("NOT_FOUND", "Back history entry not found for tab.", history_index=target_index)

    # Mutate tab cursor and visible URL/title based on nav.
    tab["history_cursor"] = target_index
    final_url = nav.get("final_url") if isinstance(nav.get("final_url"), str) and nav.get("final_url") else nav.get("request_url")
    if isinstance(final_url, str):
        tab["current_url"] = final_url
    if isinstance(nav.get("title"), str) or nav.get("title") is None:
        tab["title"] = nav.get("title")
    tab["updated_at"] = _now()

    # Mark snapshots as stale for this tab (navigation-like change).
    now = _now()
    for sn in _load("page_state_snapshots.json"):
        pass  # placeholder to avoid accidental bugs if file missing; we will load properly below
    snaps = _load("page_state_snapshots.json")
    changed_snaps = False
    for sn in snaps:
        if not isinstance(sn, dict):
            continue
        if sn.get("session_id") == session.get("id") and sn.get("tab_id") == tab.get("id") and sn.get("status") == "ready":
            # ready -> stale transition allowed
            sn["status"] = "stale"
            sn["updated_at"] = now
            changed_snaps = True

    # Persist.
    _save("browser_tabs.json", tabs)
    _save("browser_sessions.json", sessions)
    if changed_snaps:
        _save("page_state_snapshots.json", snaps)

    act = _log_action(
        actions,
        session.get("id"),
        tab.get("id"),
        "succeeded",
        result={"history_cursor": tab["history_cursor"], "current_url": tab.get("current_url")},
        related_navigation_id=nav.get("id"),
    )
    _save("browser_actions.json", actions)

    return {
        "session_id": session.get("id"),
        "tab_id": tab.get("id"),
        "history_cursor": tab.get("history_cursor"),
        "navigation": nav,
        "action": act,
    }

def browser_go_forward(**_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0231000" if __import__("os").path.isdir("./environment_mix/0231000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_01{uuid.uuid4().hex[:25]}".lower()

    def _log_action(actions, session_id, tab_id, status, error_message=None, result=None, related_navigation_id=None):
        now = _now()
        dur = int(max(0, round((time.time() - t0) * 1000)))
        row = {
            "id": _new_id("brws_act"),
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": "browser_go_forward",
            "input": {},
            "result": result,
            "related_navigation_id": related_navigation_id,
            "related_snapshot_id": None,
            "related_artifact_id": None,
            "duration_ms": dur,
            "status": status,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
        }
        actions.append(row)
        return row

    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    navs = _load("tab_navigations.json")
    actions = _load("browser_actions.json")

    session = None
    tab = None
    ready_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "ready" and isinstance(s.get("id"), str)]
    for s in ready_sessions:
        atid = s.get("active_tab_id")
        if not atid:
            continue
        t = next((tt for tt in tabs if isinstance(tt, dict) and tt.get("id") == atid and tt.get("session_id") == s["id"]), None)
        if t and t.get("status") == "open":
            session, tab = s, t
            break
    if session is None:
        for s in ready_sessions:
            t = next((tt for tt in tabs if isinstance(tt, dict) and tt.get("session_id") == s["id"] and tt.get("status") == "open"), None)
            if t:
                session, tab = s, t
                s["active_tab_id"] = t.get("id")
                s["updated_at"] = _now()
                break

    if session is None:
        if any(isinstance(s, dict) and isinstance(s.get("id"), str) for s in sessions):
            return _err("CONFLICT", "No session in 'ready' state is available for browser_go_forward.")
        return _err("NOT_FOUND", "No active session/tab found.")

    if tab is None:
        _log_action(actions, session.get("id"), None, "failed", error_message="No active tab found.")
        _save("browser_actions.json", actions)
        return _err("NOT_FOUND", "No active tab found for session.", session_id=session.get("id"))

    if not isinstance(tab.get("history_cursor"), int):
        tab["history_cursor"] = -1

    # Compute max history index from stored navigations for this tab.
    tab_navs = [n for n in navs if isinstance(n, dict) and n.get("tab_id") == tab.get("id") and n.get("session_id") == session.get("id") and isinstance(n.get("history_index"), int)]
    if not tab_navs:
        _log_action(actions, session.get("id"), tab.get("id"), "failed", error_message="No navigation history for tab.")
        _save("browser_actions.json", actions)
        return _err("CONFLICT", "No forward history entry.", rule="browser_go_forward requires at least one navigation history entry", history_cursor=tab["history_cursor"], max_history_index=None)

    max_hi = max(n["history_index"] for n in tab_navs)

    if tab["history_cursor"] >= max_hi:
        _log_action(actions, session.get("id"), tab.get("id"), "failed", error_message="No forward history entry.", result={"history_cursor": tab["history_cursor"], "max_history_index": max_hi})
        _save("browser_actions.json", actions)
        return _err(
            "CONFLICT",
            "No forward history entry.",
            rule="browser_go_forward requires browser_tabs.history_cursor < max(history_index)",
            history_cursor=tab["history_cursor"],
            max_history_index=max_hi,
        )

    target_index = tab["history_cursor"] + 1
    nav = next((n for n in tab_navs if n.get("history_index") == target_index), None)
    if nav is None:
        # Sparse history: pick nearest >= target_index
        candidates = [n for n in tab_navs if n.get("history_index") >= target_index]
        if candidates:
            nav = min(candidates, key=lambda x: x.get("history_index"))
            target_index = nav.get("history_index")
        else:
            _log_action(actions, session.get("id"), tab.get("id"), "failed", error_message="No forward history entry.", result={"history_index": target_index})
            _save("browser_actions.json", actions)
            return _err("CONFLICT", "No forward history entry.", history_cursor=tab["history_cursor"], max_history_index=max_hi)

    tab["history_cursor"] = target_index
    final_url = nav.get("final_url") if isinstance(nav.get("final_url"), str) and nav.get("final_url") else nav.get("request_url")
    if isinstance(final_url, str):
        tab["current_url"] = final_url
    if isinstance(nav.get("title"), str) or nav.get("title") is None:
        tab["title"] = nav.get("title")
    tab["updated_at"] = _now()

    # Stale ready snapshots (navigation-like change).
    snaps = _load("page_state_snapshots.json")
    changed_snaps = False
    now = _now()
    for sn in snaps:
        if not isinstance(sn, dict):
            continue
        if sn.get("session_id") == session.get("id") and sn.get("tab_id") == tab.get("id") and sn.get("status") == "ready":
            sn["status"] = "stale"
            sn["updated_at"] = now
            changed_snaps = True

    _save("browser_tabs.json", tabs)
    _save("browser_sessions.json", sessions)
    if changed_snaps:
        _save("page_state_snapshots.json", snaps)

    act = _log_action(
        actions,
        session.get("id"),
        tab.get("id"),
        "succeeded",
        result={"history_cursor": tab["history_cursor"], "current_url": tab.get("current_url")},
        related_navigation_id=nav.get("id"),
    )
    _save("browser_actions.json", actions)

    return {
        "session_id": session.get("id"),
        "tab_id": tab.get("id"),
        "history_cursor": tab.get("history_cursor"),
        "navigation": nav,
        "action": act,
    }

def browser_screenshot(name=None, selector=None, index=None, width=None, height=None, fullPage=None, highlight=None, **_extra):
    import json, os, datetime, time, uuid, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0231000" if __import__("os").path.isdir("./environment_mix/0231000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        return f"{prefix}_01{uuid.uuid4().hex[:25]}".lower()
    def _is_int_like(x):
        return (isinstance(x, int) and not isinstance(x, bool)) or (isinstance(x, float) and not isinstance(x, bool) and int(x) == x)

    def _latest_ready_snapshot(snaps, session_id, tab_id):
        rs = [s for s in snaps if isinstance(s, dict) and s.get("session_id") == session_id and s.get("tab_id") == tab_id and s.get("status") == "ready"]
        if not rs:
            return None
        def k(s):
            # prefer captured_at then updated_at then created_at
            for f in ("captured_at", "updated_at", "created_at"):
                v = s.get(f)
                if isinstance(v, str):
                    return v
            return ""
        rs.sort(key=k, reverse=True)
        return rs[0]

    def _log_action(actions, session_id, tab_id, status, tool_input, error_message=None, result=None, related_snapshot_id=None, related_artifact_id=None):
        now = _now()
        dur = int(max(0, round((time.time() - t0) * 1000)))
        row = {
            "id": _new_id("brws_act"),
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": "browser_screenshot",
            "input": tool_input,
            "result": result,
            "related_navigation_id": None,
            "related_snapshot_id": related_snapshot_id,
            "related_artifact_id": related_artifact_id,
            "duration_ms": dur,
            "status": status,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now if status in ("succeeded", "failed", "cancelled") else None,
        }
        actions.append(row)
        return row

    tool_input = {
        "name": name,
        "selector": selector,
        "index": index,
        "width": width,
        "height": height,
        "fullPage": fullPage,
        "highlight": highlight,
    }

    # Validate input types (relaxed to schema; index/width/height are "number" so allow int-like only).
    if name is not None and not isinstance(name, str):
        return _err("VALIDATION_ERROR", "name must be a string", field="name")
    if selector is not None and (not isinstance(selector, str) or not selector.strip()):
        return _err("VALIDATION_ERROR", "selector must be a non-empty string", field="selector")
    if index is not None and not _is_int_like(index):
        return _err("VALIDATION_ERROR", "index must be an integer", field="index")
    if width is not None and not _is_int_like(width):
        return _err("VALIDATION_ERROR", "width must be an integer", field="width")
    if height is not None and not _is_int_like(height):
        return _err("VALIDATION_ERROR", "height must be an integer", field="height")
    if fullPage is not None and not isinstance(fullPage, bool):
        return _err("VALIDATION_ERROR", "fullPage must be a boolean", field="fullPage")
    if highlight is not None and not isinstance(highlight, bool):
        return _err("VALIDATION_ERROR", "highlight must be a boolean", field="highlight")

    if index is not None:
        index = int(index)
        if index < 0:
            return _err("VALIDATION_ERROR", "index must be >= 0", field="index")
    if width is not None:
        width = int(width)
        if width <= 0:
            return _err("VALIDATION_ERROR", "width must be > 0", field="width")
    if height is not None:
        height = int(height)
        if height <= 0:
            return _err("VALIDATION_ERROR", "height must be > 0", field="height")

    # Default booleans
    if fullPage is None:
        fullPage = False
    if highlight is None:
        highlight = False

    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    snaps = _load("page_state_snapshots.json")
    artifacts = _load("browser_artifacts.json")
    actions = _load("browser_actions.json")

    # Resolve active ready session/tab (same strategy as other tools)
    session = None
    tab = None
    ready_sessions = [s for s in sessions if isinstance(s, dict) and s.get("status") == "ready" and isinstance(s.get("id"), str)]
    for s in ready_sessions:
        atid = s.get("active_tab_id")
        if not atid:
            continue
        t = next((tt for tt in tabs if isinstance(tt, dict) and tt.get("id") == atid and tt.get("session_id") == s["id"]), None)
        if t and t.get("status") == "open":
            session, tab = s, t
            break
    if session is None:
        for s in ready_sessions:
            t = next((tt for tt in tabs if isinstance(tt, dict) and tt.get("session_id") == s["id"] and tt.get("status") == "open"), None)
            if t:
                session, tab = s, t
                s["active_tab_id"] = t.get("id")
                s["updated_at"] = _now()
                break
    if session is None or tab is None:
        _log_action(actions, session.get("id") if session else None, tab.get("id") if tab else None, "failed", tool_input, error_message="No active session/tab available.")
        _save("browser_actions.json", actions)
        return _err("NOT_FOUND", "No active session/tab found.")

    # If index provided, validate against latest ready snapshot's clickables, but do NOT require a snapshot
    # when selector is also provided (the audit case had both selector and index; accept if any snapshot exists,
    # otherwise allow screenshot via selector-only semantics).
    related_snapshot_id = None
    if index is not None:
        snap = _latest_ready_snapshot(snaps, session["id"], tab["id"])
        if snap is None:
            # Allow screenshot to proceed when selector is provided; still record guidance in result.
            if selector is None:
                _log_action(
                    actions,
                    session["id"],
                    tab["id"],
                    "failed",
                    tool_input,
                    error_message="No clickable-elements snapshot available; call browser_get_clickable_elements first.",
                )
                _save("browser_actions.json", actions)
                return _err(
                    "CONFLICT",
                    "No clickable-elements snapshot available; call browser_get_clickable_elements first.",
                    rule="index requires an existing ready page_state_snapshots row for the tab",
                )
        else:
            related_snapshot_id = snap.get("id")
            clickables = snap.get("clickable_elements")
            if not isinstance(clickables, list):
                clickables = []
            valid_indices = set()
            for el in clickables:
                if isinstance(el, dict) and _is_int_like(el.get("index")):
                    valid_indices.add(int(el.get("index")))
            if valid_indices and index not in valid_indices:
                _log_action(
                    actions,
                    session["id"],
                    tab["id"],
                    "failed",
                    tool_input,
                    error_message="Indexed element does not exist in the latest clickable-elements snapshot.",
                    related_snapshot_id=related_snapshot_id,
                )
                _save("browser_actions.json", actions)
                return _err(
                    "NOT_FOUND",
                    "Indexed element does not exist in the latest clickable-elements snapshot.",
                    index=index,
                    guidance="Call browser_get_clickable_elements and use a valid index from the latest snapshot.",
                    snapshot_id=related_snapshot_id,
                )

    # Create artifact (simulate screenshot payload as inline_base64, available immediately).
    now = _now()
    payload = f"screenshot:{session['id']}:{tab['id']}:{now}:{uuid.uuid4().hex}".encode("utf-8")
    b64 = base64.b64encode(payload).decode("ascii")
    sha = hashlib.sha256(payload).hexdigest()

    artifact_id = _new_id("brws_art")
    screenshot_params = {
        "name": name,
        "selector": selector,
        "index": index,
        "width": width,
        "height": height,
        "fullPage": fullPage,
        "highlight": highlight,
    }

    artifact = {
        "id": artifact_id,
        "session_id": session["id"],
        "tab_id": tab["id"],
        "kind": "screenshot",
        "name": name,
        "source_url": tab.get("current_url"),
        "mime_type": "image/png",
        "byte_size": len(payload),
        "storage_backend": "inline_base64",
        "storage_key": artifact_id,
        "sha256": sha,
        "screenshot_params": screenshot_params,
        "download_filename": None,
        "download_state": None,
        "status": "available",
        "error_message": None,
        "created_at": now,
        "updated_at": now,
        "available_at": now,
    }
    artifacts.append(artifact)
    _save("browser_artifacts.json", artifacts)
    _save("browser_sessions.json", sessions)  # in case we updated active_tab_id above

    act = _log_action(
        actions,
        session["id"],
        tab["id"],
        "succeeded",
        tool_input,
        result={"artifact_id": artifact_id, "mime_type": artifact["mime_type"], "byte_size": artifact["byte_size"], "storage_backend": artifact["storage_backend"]},
        related_snapshot_id=related_snapshot_id,
        related_artifact_id=artifact_id,
    )
    _save("browser_actions.json", actions)

    return {"artifact": artifact, "content_base64": b64, "action": act}

def browser_click(index=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0231000" if __import__("os").path.isdir("./environment_mix/0231000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else []
        except Exception:
