                "status": status,
                "detail": detail,
                "latency_ms": latency_ms,
                "timestamp": _now()
            })
            _save(fname, logs)
        except Exception:
            pass

    started = time.time()
    endpoint = "browser_tab_list"

    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")

    # Ambient auth/session resolution: pick any session that can serve this call.
    session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") in ("ready", "starting", "closing", "error", "closed"):
            session = s
            break

    if session is None:
        _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "No attached browser session.")

    sid = session.get("id")
    if not sid:
        _log(endpoint, "error", detail={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Browser session not found.")

    if session.get("status") == "closed":
        _log(endpoint, "error", session_id=sid, detail={"code": "CONFLICT"})
        return _err("CONFLICT", "Browser session is closed.")

    # Require ready per business rules for non-close tools.
    if session.get("status") != "ready":
        _log(endpoint, "error", session_id=sid, detail={"code": "CONFLICT"})
        return _err("CONFLICT", "Browser session is not ready.")

    session_tabs = [t for t in tabs if isinstance(t, dict) and t.get("session_id") == sid]
    session_tabs.sort(key=lambda r: (r.get("tab_index") if isinstance(r.get("tab_index"), int) else 10**9, r.get("created_at") or ""))

    active_tab_id = session.get("active_tab_id")

    _log(endpoint, "ok", session_id=sid, tab_id=active_tab_id)
    return {
        "session_id": sid,
        "active_tab_id": active_tab_id,
        "tabs": session_tabs,
        "total": len(session_tabs)
    }

def browser_new_tab(url, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0231000" if __import__("os").path.isdir("./environment_mix/0231000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, status, session_id=None, tab_id=None, detail=None, started=None):
        try:
            fname = _ensure_request_log()
            logs = _load(fname)
            ended = time.time()
            latency_ms = None if started is None else int(round((ended - started) * 1000))
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "session_id": session_id,
                "tab_id": tab_id,
                "status": status,
                "detail": detail,
                "latency_ms": latency_ms,
                "timestamp": _now()
            })
            _save(fname, logs)
        except Exception:
            pass

    def _valid_url(u):
        if not isinstance(u, str):
            return False
        u = u.strip()
        if not u:
            return False
        # Basic scheme validation to avoid obviously invalid inputs
        return bool(re.match(r"^(https?://|file://|about:|data:)", u))

    started = time.time()
    endpoint = "browser_new_tab"

    if not _valid_url(url):
        _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid or missing url. Expected a URL starting with http://, https://, file://, about:, or data:.")

    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    navs = _load("tab_navigations.json")
    snapshots = _load("page_state_snapshots.json")

    session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") in ("ready", "starting", "closing", "error", "closed"):
            session = s
            break

    if session is None:
        _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "No attached browser session.")

    sid = session.get("id")
    if not sid:
        _log(endpoint, "error", detail={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Browser session not found.")

    if session.get("status") == "closed":
        _log(endpoint, "error", session_id=sid, detail={"code": "CONFLICT"})
        return _err("CONFLICT", "Browser session is closed.")

    if session.get("status") != "ready":
        _log(endpoint, "error", session_id=sid, detail={"code": "CONFLICT"})
        return _err("CONFLICT", "Browser session is not ready.")

    # Minimal, observable quota/rate-limit: cap tab creation to 100 tabs per session.
    session_tab_count = sum(1 for t in tabs if isinstance(t, dict) and t.get("session_id") == sid)
    if session_tab_count >= 100:
        _log(endpoint, "error", session_id=sid, detail={"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "Tab creation quota exceeded for this session.", limit=100)

    # Next available tab_index (unique per session)
    used = set()
    for t in tabs:
        if isinstance(t, dict) and t.get("session_id") == sid and isinstance(t.get("tab_index"), int):
            used.add(t["tab_index"])
    next_index = 0
    while next_index in used:
        next_index += 1

    now = _now()
    tab_id = "tab_" + uuid.uuid4().hex
    nav_id = "nav_" + uuid.uuid4().hex

    new_tab = {
        "id": tab_id,
        "session_id": sid,
        "tab_index": next_index,
        "title": None,
        "current_url": url.strip(),
        "history_cursor": 0,
        "status": "open",
        "created_at": now,
        "updated_at": now,
        "closed_at": None
    }

    # Navigation record at history_index=0
    new_nav = {
        "id": nav_id,
        "session_id": sid,
        "tab_id": tab_id,
        "history_index": 0,
        "request_url": url.strip(),
        "final_url": url.strip(),
        "referrer": None,
        "http_status": None,
        "title": None,
        "dom_content_loaded_at": None,
        "load_event_at": None,
        "status": "committed",
        "error_message": None,
        "created_at": now,
        "updated_at": now
    }

    # Mark existing ready snapshots for this tab none (new tab), nothing to stale.
    # Update session active_tab_id to new tab
    # Enforce session.active_tab_id constraint (must be a tab in same session) after insert.
    tabs.append(new_tab)
    navs.append(new_nav)

    # Update session row in-place
    updated = False
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sid:
            s["active_tab_id"] = tab_id
            s["updated_at"] = now
            updated = True
            break
    if not updated:
        _log(endpoint, "error", session_id=sid, detail={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Browser session not found.")

    # Persist
    _save("browser_tabs.json", tabs)
    _save("tab_navigations.json", navs)
    _save("browser_sessions.json", sessions)
    _save("page_state_snapshots.json", snapshots)

    _log(endpoint, "ok", session_id=sid, tab_id=tab_id)
    return {
        "session_id": sid,
        "tab": new_tab,
        "navigation": new_nav,
        "active_tab_id": tab_id
    }

def browser_close(**_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0231000" if __import__("os").path.isdir("./environment_mix/0231000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, status, session_id=None, tab_id=None, detail=None, started=None):
        try:
            fname = _ensure_request_log()
            logs = _load(fname)
            ended = time.time()
            latency_ms = None if started is None else int(round((ended - started) * 1000))
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "session_id": session_id,
                "tab_id": tab_id,
                "status": status,
                "detail": detail,
                "latency_ms": latency_ms,
                "timestamp": _now()
            })
            _save(fname, logs)
        except Exception:
            pass

    started = time.time()
    endpoint = "browser_close"

    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")

    session = None
    for s in sessions:
        if isinstance(s, dict) and s.get("status") in ("ready", "starting", "closing", "error", "closed"):
            session = s
            break

    if session is None:
        _log(endpoint, "error", detail={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "No attached browser session.")

    sid = session.get("id")
    if not sid:
        _log(endpoint, "error", detail={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Browser session not found.")

    if session.get("status") == "closed":
        _log(endpoint, "error", session_id=sid, detail={"code": "CONFLICT"})
        return _err("CONFLICT", "Browser session is already closed.")

    now = _now()

    # Transition session to closing (if not already), then closed
    # Enforce lifecycle transitions
    allowed = {
        "starting": {"ready", "error", "closing"},
        "ready": {"closing", "error"},
        "closing": {"closed", "error"},
        "closed": set(),
        "error": {"closing", "closed"},
    }

    current = session.get("status")
    if current not in allowed:
        _log(endpoint, "error", session_id=sid, detail={"code": "INVALID_TRANSITION"})
        return _err("INVALID_TRANSITION", f"Unknown session status '{current}'.")

    # If already closing, allow proceeding to closed
    if current != "closing":
        if "closing" not in allowed.get(current, set()):
            _log(endpoint, "error", session_id=sid, detail={"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", f"Cannot transition session from {current} to closing.")
        # Set to closing
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == sid:
                s["status"] = "closing"
                s["updated_at"] = now
                break

    # Close all open/closing/crashed tabs => closed
    for t in tabs:
        if not isinstance(t, dict): 
            continue
        if t.get("session_id") != sid:
            continue
        st = t.get("status")
        if st in ("open", "closing", "crashed"):
            # open->closing->closed, closing->closed, crashed->closing->closed
            t["status"] = "closed"
            t["closed_at"] = now
            t["updated_at"] = now

    # Set session to closed, clear active_tab_id, set closed_at
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sid:
            # closing -> closed must be allowed
            if "closed" not in allowed.get(s.get("status"), set()) and s.get("status") != "closed":
                _log(endpoint, "error", session_id=sid, detail={"code": "INVALID_TRANSITION"})
                return _err("INVALID_TRANSITION", f"Cannot transition session from {s.get('status')} to closed.")
            s["status"] = "closed"
            s["active_tab_id"] = None
            s["closed_at"] = now
            s["updated_at"] = now
            break

    _save("browser_tabs.json", tabs)
    _save("browser_sessions.json", sessions)

    _log(endpoint, "ok", session_id=sid)
    return {
        "session_id": sid,
        "status": "closed",
        "closed_at": now
    }

def browser_create_session(apiKey, browser_engine=None, headless=None, locale=None, timezone=None, initialUrl=None, client_connection_id=None, **_extra):
    import json, os, datetime, uuid, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0231000" if __import__("os").path.isdir("./environment_mix/0231000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        return f"{prefix}_01{uuid.uuid4().hex[:25]}".lower()

    def _log_action(actions, status_str, input_payload, error_message=None, result=None, session_id=None, tab_id=None):
        now = _now()
        dur = int(max(0, round((time.time() - t0) * 1000)))
        row = {
            "id": _new_id("brws_act"),
            "session_id": session_id,
            "tab_id": tab_id,
            "tool_name": "browser_create_session",
            "input": input_payload,
            "result": result,
            "related_navigation_id": None,
            "related_snapshot_id": None,
            "related_artifact_id": None,
            "duration_ms": dur,
            "status": status_str,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now if status_str in ("succeeded", "failed", "cancelled") else None,
        }
        actions.append(row)
        return row

    tool_input = {
        "apiKey": apiKey,
        "browser_engine": browser_engine,
        "headless": headless,
        "locale": locale,
        "timezone": timezone,
        "initialUrl": initialUrl,
        "client_connection_id": client_connection_id,
    }

    if apiKey is None or not isinstance(apiKey, str) or not apiKey.strip():
        return _err("VALIDATION_ERROR", "apiKey is required and must be a non-empty string.", field="apiKey")

    # Authenticate only if api_keys.json exists and has client-visible fields.
    api_keys = _load("api_keys.json")
    cred = None
    if api_keys:
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            for fn in ("id", "apiKey", "key", "value", "token", "client_visible", "client_value", "public"):
                if apiKey == k.get(fn):
                    cred = k
                    break
            if cred:
                break
        if cred is None:
            actions = _load("browser_actions.json")
            _log_action(actions, "failed", tool_input, error_message="Invalid apiKey.")
            _save("browser_actions.json", actions)
            return _err("UNAUTHORIZED", "Invalid apiKey.")
    else:
        cred = {"id": None}

    if browser_engine is None:
        browser_engine = "chromium"
    if browser_engine not in ("chromium", "firefox", "webkit"):
        return _err("VALIDATION_ERROR", "browser_engine must be one of: chromium, firefox, webkit", field="browser_engine")

    if headless is None:
        headless = True
    if not isinstance(headless, bool):
        return _err("VALIDATION_ERROR", "headless must be a boolean", field="headless")
    if locale is not None and not isinstance(locale, str):
        return _err("VALIDATION_ERROR", "locale must be a string", field="locale")
    if timezone is not None and not isinstance(timezone, str):
        return _err("VALIDATION_ERROR", "timezone must be a string", field="timezone")
    if initialUrl is not None and (not isinstance(initialUrl, str) or not initialUrl.strip()):
        return _err("VALIDATION_ERROR", "initialUrl must be a non-empty string", field="initialUrl")
    if client_connection_id is not None and not isinstance(client_connection_id, str):
        return _err("VALIDATION_ERROR", "client_connection_id must be a string", field="client_connection_id")

    sessions = _load("browser_sessions.json")
    tabs = _load("browser_tabs.json")
    navs = _load("tab_navigations.json")
    actions = _load("browser_actions.json")

    # Quota: limit number of non-closed sessions (simple service-side safety)
    active_count = 0
    for s in sessions:
        if isinstance(s, dict) and s.get("status") in ("starting", "ready", "closing", "error"):
            active_count += 1
    if active_count >= 50:
        _log_action(actions, "failed", tool_input, error_message="Session quota exceeded.")
        _save("browser_actions.json", actions)
        return _err("QUOTA_EXCEEDED", "Session quota exceeded.", limit=50)

    now = _now()
    session_id = _new_id("brws_sess")
    sess = {
        "id": session_id,
        "client_connection_id": client_connection_id,
        "browser_engine": browser_engine,
        "headless": headless,
        "locale": locale,
        "timezone": timezone,
        "active_tab_id": None,
        "status": "ready",
        "last_error": None,
        "created_at": now,
        "updated_at": now,
        "closed_at": None,
    }
    sessions.append(sess)

    created_tab = None
    created_nav = None
    if initialUrl is not None:
        # next available tab_index for this session
        existing_idx = [tt.get("tab_index") for tt in tabs if isinstance(tt, dict) and tt.get("session_id") == session_id and isinstance(tt.get("tab_index"), int)]
        next_idx = (max(existing_idx) + 1) if existing_idx else 0
        tab_id = _new_id("brws_tab")
        created_tab = {
            "id": tab_id,
            "session_id": session_id,
            "tab_index": next_idx,
            "title": None,
            "current_url": initialUrl,
            "history_cursor": 0,
            "status": "open",
            "created_at": now,
            "updated_at": now,
            "closed_at": None,
        }
        tabs.append(created_tab)
        sess["active_tab_id"] = tab_id
        sess["updated_at"] = now

        nav_id = _new_id("brws_nav")
        created_nav = {
            "id": nav_id,
            "session_id": session_id,
            "tab_id": tab_id,
            "history_index": 0,
            "request_url": initialUrl,
            "final_url": None,
            "referrer": None,
            "http_status": None,
            "title": None,
            "dom_content_loaded_at": None,
            "load_event_at": None,
            "status": "requested",
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        navs.append(created_nav)

    _save("browser_sessions.json", sessions)
    if created_tab is not None:
        _save("browser_tabs.json", tabs)
        _save("tab_navigations.json", navs)

    act = _log_action(
        actions,
        "succeeded",
        tool_input,
        result={"session_id": session_id, "active_tab_id": sess.get("active_tab_id")},
        session_id=session_id,
        tab_id=sess.get("active_tab_id"),
    )
    _save("browser_actions.json", actions)

    out = {"session": sess, "action": act, "credential_id": cred.get("id")}
    if created_tab is not None:
        out["initial_tab"] = created_tab
        out["initial_navigation"] = created_nav
    return out

def browser_list_sessions(apiKey, status=None, created_after=None, created_before=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, base64, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0231000" if __import__("os").path.isdir("./environment_mix/0231000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        return f"{prefix}_01{uuid.uuid4().hex[:25]}".lower()

    def _parse_dt(s):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, "created_after/created_before must be RFC3339 timestamp strings"
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]), None
            return datetime.datetime.fromisoformat(s), None
        except ValueError:
            return None, "created_after/created_before must be RFC3339 timestamps"

    def _encode_cursor(offset):
        raw = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        if c is None:
            return 0, None
        if not isinstance(c, str) or not c:
            return None, "cursor must be a non-empty string"
        pad = "=" * ((4 - (len(c) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off, None
            return None, "cursor is invalid"
        except Exception:
            return None, "cursor is invalid"

    def _log_action(actions, status_str, input_payload, error_message=None, result=None):
        now = _now()
        dur = int(max(0, round((time.time() - t0) * 1000)))
        row = {
            "id": _new_id("brws_act"),
            "session_id": None,
            "tab_id": None,
            "tool_name": "browser_list_sessions",
            "input": input_payload,
            "result": result,
            "related_navigation_id": None,
            "related_snapshot_id": None,
            "related_artifact_id": None,
            "duration_ms": dur,
            "status": status_str,
            "error_message": error_message,
            "created_at": now,
            "updated_at": now,
            "started_at": now,
            "finished_at": now if status_str in ("succeeded", "failed", "cancelled") else None,
        }
        actions.append(row)
        return row

    tool_input = {
        "apiKey": apiKey,
        "status": status,
        "created_after": created_after,
        "created_before": created_before,
        "limit": limit,
        "cursor": cursor,
        "order": order,
    }

    # IMPORTANT: Relax apiKey validation to vendor schema: only must be a string (can be "138" etc).
    if apiKey is None or not isinstance(apiKey, str):
        actions = _load("browser_actions.json")
        _log_action(actions, "failed", tool_input, error_message="apiKey is required and must be a string.")
        _save("browser_actions.json", actions)
        return _err("VALIDATION_ERROR", "apiKey is required and must be a string.", field="apiKey")

    if status is not None and status not in ("starting", "ready", "closing", "closed", "error"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=["starting", "ready", "closing", "closed", "error"])

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")

    if order is None:
        order = "created_at_desc"
    if order not in ("created_at_asc", "created_at_desc"):
        return _err("VALIDATION_ERROR", "Invalid order.", field="order", allowed=["created_at_asc", "created_at_desc"])

    created_after_dt, err1 = _parse_dt(created_after)
    if err1:
        return _err("VALIDATION_ERROR", err1, field="created_after")
    created_before_dt, err2 = _parse_dt(created_before)
    if err2:
        return _err("VALIDATION_ERROR", err2, field="created_before")

    offset, cerr = _decode_cursor(cursor)
    if cerr:
        return _err("VALIDATION_ERROR", cerr, field="cursor")

    # Authenticate only if api_keys.json exists; otherwise allow (offline/local mode).
    api_keys = _load("api_keys.json")
    if api_keys:
        cred = None
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            for fn in ("id", "apiKey", "key", "value", "token", "client_visible", "client_value", "public"):
                if apiKey == k.get(fn):
                    cred = k
                    break
            if cred:
                break
        if cred is None:
            actions = _load("browser_actions.json")
            _log_action(actions, "failed", tool_input, error_message="Invalid apiKey.")
            _save("browser_actions.json", actions)
            return _err("UNAUTHORIZED", "Invalid apiKey.")

    sessions = _load("browser_sessions.json")
    # Filter
    filtered = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        ca = s.get("created_at")
        ca_dt, _ = _parse_dt(ca) if isinstance(ca, str) else (None, None)
        if created_after_dt and ca_dt and not (ca_dt > created_after_dt):
            continue
        if created_before_dt and ca_dt and not (ca_dt < created_before_dt):
            continue
        filtered.append(s)

    # Sort
    def sort_key(s):
        v = s.get("created_at")
        return v if isinstance(v, str) else ""
    filtered.sort(key=sort_key, reverse=(order == "created_at_desc"))

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    actions = _load("browser_actions.json")
    act = _log_action(actions, "succeeded", tool_input, result={"returned": len(page), "total": total, "has_more": has_more})
    _save("browser_actions.json", actions)

    return {
        "sessions": page,
        "total": total,
        "limit": limit,
        "cursor": next_cursor,
        "has_more": has_more,
        "order": order,
        "action": act,
    }

def browser_get_session(apiKey, session_id, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0231000" if __import__("os").path.isdir("./environment_mix/0231000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                d = json.load(f)
                return d if isinstance(d, list) else []
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    # Relax apiKey validation to vendor schema: must be a string (not necessarily non-empty in all environments)
    if apiKey is None or not isinstance(apiKey, str):
        return _err("VALIDATION_ERROR", "apiKey is required and must be a string.", field="apiKey")
    if session_id is None or not isinstance(session_id, str) or not session_id.strip():
        return _err("VALIDATION_ERROR", "session_id is required and must be a non-empty string.", field="session_id")

    api_keys = _load("api_keys.json")
    cred = None
    if api_keys:
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            for fn in ("id", "apiKey", "key", "value", "token", "client_visible", "client_value", "public"):
                if apiKey == k.get(fn):
                    cred = k
                    break
            if cred:
                break
        if cred is None:
            return _err("UNAUTHORIZED", "Invalid apiKey.")
    else:
        cred = {"id": None}

    sessions = _load("browser_sessions.json")
    sess = next((s for s in sessions if isinstance(s, dict) and s.get("id") == session_id), None)
    if not sess:
        return _err("NOT_FOUND", "Session not found.")
    return {"session": sess, "credential_id": cred.get("id")}
